head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ssMarket = "N"; // 시장 콤보 초기 세팅 완료 여부(초기 setValue 시 onchange 재조회 방지)
scwin.skw = ""; // 제출인명 필터 키워드
scwin.tpcd = ""; // 세션의 시장구분 (onpageload 에서 부모 화면 값 취득)

///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★
스크립트 수작업 유의사항

*/
scwin.onpageload = async function () {
    try {
        // 구 최상위 즉시 실행($c.win.getParent().js_com_market) 이동 — 부모 화면 부재 가드
        scwin.tpcd = $c.win.getParent()?.js_com_market ?? "";
        await scwin.code1Sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.onpageload" });
    }
};

scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.combo_market_onselchange = async function (info) {
    try {
        if (scwin.ssMarket === "Y") {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.combo_market_onselchange" });
    }
};

scwin.img_search_onclick = function (e) {
    try {
        scwin.JongmokName();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00008.img_search_onclick" });
    }
};

scwin.txb_jongmokName_onkeydown = function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            scwin.JongmokName();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00008.txb_jongmokName_onkeydown" });
    }
};

scwin.grd_jongmok_onkeydown = async function (e) {
    try {
        if (Number(e.keyCode) === 13) {
            await scwin.Confirm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.grd_jongmok_onkeydown" });
    }
};

scwin.grd_jongmok_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.Confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00008.grd_jongmok_oncelldblclick" });
    }
};

